func (r *mutationResolver) CreateAgentEvalCase(ctx context.Context, input gqlmodel.CreateAgentEvalCaseInput) (*gqlmodel.AgentEvalCaseCapture, error) {
	authCtx, err := r.requirePermission(ctx, permission.ResourceAgentEvalSuite, permission.OpCreate)
	if err != nil {
		return nil, err
	}

	tenant := tenantInfo(authCtx)
	actor := actorutil.FromAuthContext(authCtx)
	var captured *services.EvalCaseCapture
	switch {
	case evalCaseSources(input) != 1:
		return nil, errortypes.NewValidationError(
			"input",
			errortypes.ErrInvalid,
			"Create a case from exactly one of a message, a proposal, a rating or a curated question",
		)
	case input.FromMessage != nil:
		request, reqErr := evalCaseFromMessage(input.FromMessage)
		if reqErr != nil {
			return nil, reqErr
		}
		request.TenantInfo = tenant
		captured, err = r.agentEvalCaseService.CreateFromMessage(ctx, request, actor)
	case input.FromProposal != nil:
		proposalID, parseErr := pulid.MustParse(input.FromProposal.ProposalID)
		if parseErr != nil {
			return nil, parseErr
		}
		captured, err = r.agentEvalCaseService.CreateFromProposal(ctx, &services.CreateEvalCaseFromProposalRequest{
			ProposalID: proposalID,
			Title:      derefString(input.FromProposal.Title),
			TenantInfo: tenant,
		}, actor)
	case input.FromFeedback != nil:
		feedbackID, parseErr := pulid.MustParse(input.FromFeedback.FeedbackID)
		if parseErr != nil {
			return nil, parseErr
		}
		captured, err = r.agentEvalCaseService.CreateFromFeedback(ctx, &services.CreateEvalCaseFromFeedbackRequest{
			FeedbackID: feedbackID,
			Title:      derefString(input.FromFeedback.Title),
			TenantInfo: tenant,
		}, actor)
	default:
		request, reqErr := evalCaseCurated(input.Curated)
		if reqErr != nil {
			return nil, reqErr
		}
		request.TenantInfo = tenant
		captured, err = r.agentEvalCaseService.CreateCurated(ctx, request, actor)
	}
	if err != nil {
		return nil, err
	}

	return &gqlmodel.AgentEvalCaseCapture{EvalCase: captured.Case, Duplicate: captured.Duplicate}, nil
}

